<?php require_once 'db.php';require_once 'functions.php';$u=need_role($pdo,['admin']);$msg='';$err='';$rs=$pdo->query("SELECT id,name FROM roles ORDER BY FIELD(name,'customer','seller','staff','manager','admin')")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['action'];$uid=(int)$_POST['user_id'];$rid=(int)($_POST['role_id']??0);if($a==='assign'){try{$pdo->prepare('INSERT INTO user_roles(user_id,role_id) VALUES(?,?)')->execute([$uid,$rid]);audit($pdo,$u['id'],'ASSIGN_ROLE','user_roles',null,null,['user_id'=>$uid,'role_id'=>$rid]);$msg='Role diberikan.';}catch(Throwable $e){$err='Role sudah ada atau data tidak valid.';}}if($a==='remove'){ $s=$pdo->prepare('SELECT name FROM roles WHERE id=?');$s->execute([$rid]);$r=$s->fetch();if($r&&$r['name']==='customer')$err='Role customer dasar tidak dihapus.';elseif($uid===$u['id']&&$r&&$r['name']==='admin')$err='Role admin akun aktif tidak dihapus.';else{$pdo->prepare('DELETE FROM user_roles WHERE user_id=? AND role_id=?')->execute([$uid,$rid]);$msg='Role dicabut.';}}if($a==='toggle'){$target=$uid;if($target===$u['id'])$err='Akun admin aktif tidak dinonaktifkan di sini.';else{$s=$pdo->prepare('SELECT is_active FROM users WHERE id=?');$s->execute([$target]);$v=$s->fetch();$pdo->prepare('UPDATE users SET is_active=? WHERE id=?')->execute([(int)!$v['is_active'],$target]);$msg='Status akun diubah.';}}}
$rows=$pdo->query("SELECT u.*,GROUP_CONCAT(CONCAT(ur.role_id,':',r.name) SEPARATOR '|') role_data FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id GROUP BY u.id ORDER BY u.id DESC")->fetchAll();?><?php $pageTitle='Pengguna & peran'; include 'layout_top.php'; ?><h1>Users & Roles</h1><p class="muted">Buyer dan employee tetap satu akun di <b>users</b>; perbedaan fungsi berasal dari <b>user_roles</b>.</p><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><div class="card"><table><thead><tr><th>User</th><th>Roles</th><th>Assign</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><?=e($x['name'])?><br><small><?=e($x['email'])?></small></td><td><?php foreach(explode('|',$x['role_data']??'') as $rd){if($rd==='')continue;[$id,$name]=array_pad(explode(':',$rd,2),2,'');?><span class="badge"><?=e(label_role($name))?></span><?php if($name!=='customer'):?><form method="post" style="display:inline"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="user_id" value="<?=$x['id']?>"><input type="hidden" name="role_id" value="<?=$id?>"><button class="btn-xs danger">x</button></form><?php endif;}?></td><td><form class="actions" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><input type="hidden" name="action" value="assign"><input type="hidden" name="user_id" value="<?=$x['id']?>"><select name="role_id" required><option value="">Choose</option><?php foreach($rs as $r):?><option value="<?=$r['id']?>"><?=e(label_role($r['name']))?></option><?php endforeach;?></select><button class="btn-sm primary">Assign</button></form></td><td><?=$x['is_active']?'Active':'Inactive'?></td><td><?php if($x['id']!=$u['id']):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="user_id" value="<?=$x['id']?>"><button class="btn-sm secondary">Toggle</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php include 'layout_bottom.php'; ?>
